compile.workshop:
settings
{
	main
	{
		Mode Name: "Ｆｒｅｅ ｆｏｒ ａｌｌ"
		Description: "ａxｂ"
	}
	modes
	{
		Deathmatch
		{
			enabled maps
			{
				Workshop Island
			}
		}
	}
}

variables {
    global:
        0: value
}

rule ("issue 530 string-modifier settings") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(value, Custom String("ａ{0}ｂ", Match Time));
    }
}

